source("pre.R")
k <- jwk_oct(as.raw(1:32))
show <- function(label, expr) { r <- try_(expr); cat(sprintf("%-26s", label)); if (inherits(r, "err")) cat("ERR", r$cls[1], r$msg, "\n") else { p <- strsplit(r, ".", fixed = TRUE)[[1]]; cat(rawToChar(zujose:::b64url_decode(p[1], "x", NULL)), rawToChar(zujose:::b64url_decode(p[2], "x", NULL)), "\n") } }
show("auth_time POSIXct", jwt_encode(list(auth_time = as.POSIXct(1700000000, tz = "UTC")), k, "HS256", issued_at = FALSE))
show("updated_at Date", jwt_encode(list(d = as.Date("2030-01-01")), k, "HS256", issued_at = FALSE))
show("factor", jwt_encode(list(f = factor("a")), k, "HS256", issued_at = FALSE))
show("named vec", jwt_encode(list(v = c(a = 1, b = 2)), k, "HS256", issued_at = FALSE))
show("exp POSIXlt", jwt_encode(list(exp = as.POSIXlt("2030-01-01", tz = "UTC")), k, "HS256", issued_at = FALSE))
show("exp difftime", jwt_encode(list(exp = as.difftime(5, units = "mins")), k, "HS256", issued_at = FALSE))
show("exp int", jwt_encode(list(exp = 1700000000L), k, "HS256", issued_at = FALSE))
show("exp pre-1970", jwt_encode(list(exp = as.POSIXct(-0.5, tz = "UTC")), k, "HS256", issued_at = FALSE))
show("iat logical TRUE claim", jwt_encode(list(iat = TRUE), k, "HS256"))
show("issued_at NA", jwt_encode(list(), k, "HS256", issued_at = NA))
show("claims unnamed", jwt_encode(list(1), k, "HS256"))
show("claims dup", jwt_encode(list(a = 1, a = 2), k, "HS256"))
show("claims char vec", jwt_encode(c(a = "1"), k, "HS256"))
show("header typ NULL", jwt_encode(list(), k, "HS256", header = list(typ = NULL), issued_at = FALSE))
show("header cty", jwt_encode(list(), k, "HS256", header = list(typ = "JWT", cty = "JWT"), issued_at = FALSE))
show("expires_in 1.5", jwt_encode(list(), k, "HS256", expires_in = 1.5, issued_at = FALSE))
show("expires_in 2.5", jwt_encode(list(), k, "HS256", expires_in = 2.5, issued_at = TRUE))
show("expires_in difftime .5h", jwt_encode(list(), k, "HS256", expires_in = as.difftime(0.5, units = "hours")))
show("not_before>expires", jwt_encode(list(), k, "HS256", expires_in = 5, not_before = 60))
# b64 false NUL payload
r <- try_(jws_sign(as.raw(c(0x61, 0, 0x62)), k, "HS256", b64 = FALSE, detached = TRUE)); cat("b64=FALSE NUL detached:", if (inherits(r, "err")) paste(r$cls[1], r$msg) else r, "\n")
# public key with key_ops sign
pk <- jwk_public(jwk_generate("EC", key_ops = c("sign", "verify"))); cat(jwk_json(pk), "\n")
r <- try_(jws_verify(jws_sign("p", jwk_generate("EC", key_ops = "sign"), "ES256"), pk, "ES256")); cat(class(r)[1], "\n")
k2 <- jwk_generate("EC", key_ops = "sign", alg = "ES256"); t <- jws_sign("p", k2); r <- try_(jws_verify(t, jwk_public(k2), "ES256")); cat("sign-only key: verify with its jwk_public():", if (inherits(r, "err")) paste(r$cls[1], r$msg) else "ok", "\n")
k3 <- jwk_generate("EC", key_ops = "deriveKey"); t <- try_(jwe_encrypt("p", jwk_public(k3), "ECDH-ES", "A128GCM")); cat("deriveKey key: encrypt to its jwk_public():", if (inherits(t, "err")) paste(t$cls[1], t$msg) else "ok", "\n")
k4 <- jwk_generate("RSA", key_ops = "unwrapKey"); t <- try_(jwe_encrypt("p", jwk_public(k4), "RSA-OAEP", "A128GCM")); cat("unwrapKey RSA: encrypt to its jwk_public():", if (inherits(t, "err")) paste(t$cls[1], t$msg) else "ok", "\n")
k5 <- jwk_generate("RSA", key_ops = c("wrapKey", "unwrapKey")); t <- try_(jwe_encrypt("p", jwk_public(k5), "RSA-OAEP", "A128GCM")); cat("wrap+unwrap RSA: encrypt to its jwk_public():", if (inherits(t, "err")) paste(t$cls[1], t$msg) else "ok", "\n")
